import React, { Component } from 'react';
import { Card, Table, Icon, Button, Spin, Alert, Input, Dropdown, Menu, Modal, message } from 'antd';

const { Search } = Input;

class ThematicAreaList extends Component {
    constructor(props) {
        super(props);
        this.state = {
            organisationUnits: [], // Level 2 - Thematic Areas
            projects: {}, // Level 3 - Projects by thematic area
            programs: {}, // Programs by project
            loading: false,
            projectsLoading: {}, // Loading state for projects
            programsLoading: {}, // Loading state for programs
            error: null,
            expandedRowKeys: [],
            projectExpandedRowKeys: {}, // Track expanded projects for each thematic area
            searchValue: '',
            filteredOrganisationUnits: [],
            allProjectsLoaded: false,
            allProgramsLoaded: false,
            deletingProgramId: null, // Track which program is being deleted
            deletingThematicAreaId: null // Track which thematic area is being deleted
        };
        this._isMounted = false;
    }

    componentDidMount() {
        this._isMounted = true;
        this.fetchThematicAreas();
    }

    componentWillUnmount() {
        this._isMounted = false;
    }

    fetchThematicAreas = () => {
        if (!this._isMounted) return;

        this.setState({ loading: true, error: null });

        fetch(`http://44.205.112.15:8080/api/29/organisationUnits?level=2`, {
            headers: {
                'Authorization': 'Basic ' + btoa(`admin:district`),
                'Content-Type': 'application/json'
            }
        })
            .then(response => {
                if (!response.ok) throw new Error('Network response was not ok');
                return response.json();
            })
            .then(data => {
                if (this._isMounted) {
                    this.setState({
                        organisationUnits: data.organisationUnits || [],
                        filteredOrganisationUnits: data.organisationUnits || [],
                        loading: false
                    });
                }
            })
            .catch(error => {
                console.error('Error fetching thematic areas:', error);
                if (this._isMounted) {
                    this.setState({
                        error: 'Failed to fetch thematic areas. Please try again.',
                        loading: false
                    });
                }
            });
    };

    // Fetch projects (level 3) for a thematic area (level 2)
    fetchProjectsInThematicArea = (thematicAreaId) => {
        if (!this._isMounted) return;

        this.setState(prevState => ({
            projectsLoading: {
                ...prevState.projectsLoading,
                [thematicAreaId]: true
            }
        }));

        fetch(`http://44.205.112.15:8080/api/29/organisationUnits?filter=parent.id:eq:${thematicAreaId}&level=3`, {
            headers: {
                'Authorization': 'Basic ' + btoa(`admin:district`),
                'Content-Type': 'application/json'
            }
        })
            .then(response => {
                if (!response.ok) throw new Error('Network response was not ok');
                return response.json();
            })
            .then(data => {
                if (this._isMounted) {
                    this.setState(prevState => ({
                        projects: {
                            ...prevState.projects,
                            [thematicAreaId]: data.organisationUnits || []
                        },
                        projectsLoading: {
                            ...prevState.projectsLoading,
                            [thematicAreaId]: false
                        }
                    }));
                }
            })
            .catch(error => {
                console.error('Error fetching projects:', error);
                if (this._isMounted) {
                    this.setState(prevState => ({
                        projects: {
                            ...prevState.projects,
                            [thematicAreaId]: []
                        },
                        projectsLoading: {
                            ...prevState.projectsLoading,
                            [thematicAreaId]: false
                        }
                    }));
                }
            });
    };

    // Fetch programs for a specific project
    fetchProgramsInProject = (projectId) => {
        if (!this._isMounted) return;

        this.setState(prevState => ({
            programsLoading: {
                ...prevState.programsLoading,
                [projectId]: true
            }
        }));

        fetch(`http://44.205.112.15:8080/api/29/programs?filter=organisationUnits.id:eq:${projectId}&fields=id,displayName,code,programType`, {
            headers: {
                'Authorization': 'Basic ' + btoa(`admin:district`),
                'Content-Type': 'application/json'
            }
        })
            .then(response => {
                if (!response.ok) throw new Error('Network response was not ok');
                return response.json();
            })
            .then(data => {
                if (this._isMounted) {
                    this.setState(prevState => ({
                        programs: {
                            ...prevState.programs,
                            [projectId]: data.programs || []
                        },
                        programsLoading: {
                            ...prevState.programsLoading,
                            [projectId]: false
                        }
                    }));
                }
            })
            .catch(error => {
                console.error('Error fetching programs:', error);
                if (this._isMounted) {
                    this.setState(prevState => ({
                        programs: {
                            ...prevState.programs,
                            [projectId]: []
                        },
                        programsLoading: {
                            ...prevState.programsLoading,
                            [projectId]: false
                        }
                    }));
                }
            });
    };

    // Fetch all data for comprehensive search
    fetchAllData = async () => {
        if (this.state.allProjectsLoaded && this.state.allProgramsLoaded) return;

        const { organisationUnits } = this.state;

        try {
            // First, fetch all projects for all thematic areas
            const projectPromises = organisationUnits.map(unit =>
                fetch(`http://44.205.112.15:8080/api/29/organisationUnits?filter=parent.id:eq:${unit.id}&level=3`, {
                    method: 'GET',
                    headers: {
                        'Authorization': 'Basic ' + btoa(`admin:district`),
                        'Content-Type': 'application/json'
                    }
                })
                    .then(response => response.json())
                    .then(data => ({ thematicAreaId: unit.id, projects: data.organisationUnits || [] }))
                    .catch(error => {
                        console.error(`Error fetching projects for ${unit.id}:`, error);
                        return { thematicAreaId: unit.id, projects: [] };
                    })
            );

            const projectResults = await Promise.all(projectPromises);
            const allProjects = {};
            const allProjectsList = [];

            projectResults.forEach(result => {
                allProjects[result.thematicAreaId] = result.projects;
                allProjectsList.push(...result.projects);
            });

            if (this._isMounted) {
                this.setState({
                    projects: allProjects,
                    allProjectsLoaded: true
                });
            }

            // Then, fetch all programs for all projects
            const programPromises = allProjectsList.map(project =>
                fetch(`http://44.205.112.15:8080/api/29/programs?filter=organisationUnits.id:eq:${project.id}&fields=id,displayName,code,programType`, {
                    method: 'GET',
                    headers: {
                        'Authorization': 'Basic ' + btoa(`admin:district`),
                        'Content-Type': 'application/json'
                    }
                })
                    .then(response => response.json())
                    .then(data => ({ projectId: project.id, programs: data.programs || [] }))
                    .catch(error => {
                        console.error(`Error fetching programs for ${project.id}:`, error);
                        return { projectId: project.id, programs: [] };
                    })
            );

            const programResults = await Promise.all(programPromises);
            const allPrograms = {};

            programResults.forEach(result => {
                allPrograms[result.projectId] = result.programs;
            });

            if (this._isMounted) {
                this.setState({
                    programs: allPrograms,
                    allProgramsLoaded: true
                });
            }
        } catch (error) {
            console.error('Error fetching all data:', error);
        }
    };

    handleThematicAreaExpand = (expanded, record) => {
        if (expanded && !this.state.projects[record.id]) {
            this.fetchProjectsInThematicArea(record.id);
        }
    };

    handleProjectExpand = (expanded, record, thematicAreaId) => {
        if (expanded && !this.state.programs[record.id]) {
            this.fetchProgramsInProject(record.id);
        }

        // Update expanded project keys for this thematic area
        this.setState(prevState => ({
            projectExpandedRowKeys: {
                ...prevState.projectExpandedRowKeys,
                [thematicAreaId]: expanded
                    ? [...(prevState.projectExpandedRowKeys[thematicAreaId] || []), record.id]
                    : (prevState.projectExpandedRowKeys[thematicAreaId] || []).filter(key => key !== record.id)
            }
        }));
    };

    handleSearch = async (value) => {
        const { organisationUnits } = this.state;

        if (!value.trim()) {
            this.setState({
                searchValue: value,
                filteredOrganisationUnits: organisationUnits,
                expandedRowKeys: [],
                projectExpandedRowKeys: {}
            });
            return;
        }

        // Ensure all data is loaded for comprehensive search
        if (!this.state.allProjectsLoaded || !this.state.allProgramsLoaded) {
            await this.fetchAllData();
        }

        const searchTerm = value.toLowerCase();
        const filteredUnits = [];
        const autoExpandKeys = [];
        const autoExpandProjects = {};

        organisationUnits.forEach(unit => {
            // Check if thematic area matches
            const unitMatches = unit.displayName.toLowerCase().includes(searchTerm) ||
                unit.id.toLowerCase().includes(searchTerm) ||
                (unit.code && unit.code.toLowerCase().includes(searchTerm));

            // Check projects and programs
            const unitProjects = this.state.projects[unit.id] || [];
            let hasMatchingProject = false;
            let matchingProjectIds = [];

            unitProjects.forEach(project => {
                const projectMatches = project.displayName.toLowerCase().includes(searchTerm) ||
                    project.id.toLowerCase().includes(searchTerm) ||
                    (project.code && project.code.toLowerCase().includes(searchTerm));

                // Check programs in this project
                const projectPrograms = this.state.programs[project.id] || [];
                const programMatches = projectPrograms.some(program =>
                    program.displayName.toLowerCase().includes(searchTerm) ||
                    program.id.toLowerCase().includes(searchTerm) ||
                    (program.code && program.code.toLowerCase().includes(searchTerm))
                );

                if (projectMatches || programMatches) {
                    hasMatchingProject = true;
                    matchingProjectIds.push(project.id);
                }
            });

            // Include the thematic area if it or its children match
            if (unitMatches || hasMatchingProject) {
                filteredUnits.push(unit);

                // Auto-expand if children match
                if (hasMatchingProject) {
                    autoExpandKeys.push(unit.id);
                    autoExpandProjects[unit.id] = matchingProjectIds;
                }
            }
        });

        this.setState({
            searchValue: value,
            filteredOrganisationUnits: filteredUnits,
            expandedRowKeys: autoExpandKeys,
            projectExpandedRowKeys: autoExpandProjects
        });
    };

    handleProgramClick = (program, project) => {
        const redirectUrl = `/sims-web-maintenance/#/edit/programSection/program/${program.id}`;
        window.location.href = redirectUrl;
    };

    handleProgramView = (program, project) => {
        // Navigate based on program type
        let redirectUrl;

        if (program.programType === 'WITHOUT_REGISTRATION') {
            // For WITHOUT_REGISTRATION (Forms)programs, go to capture (Forms) app
            redirectUrl = `/sims-web-capture/#/?orgUnitId=${project.id}&programId=${program.id}`;
        } else if (program.programType === 'WITH_REGISTRATION') {
            // For WITH_REGISTRATION (Spreadsheet) programs, go to aggregate data entry (Spreadsheet) app
            redirectUrl = `/sims-web-aggregate-data-entry/#/?orgUnitId=${project.id}`;
        }

        window.location.href = redirectUrl;
    };

    handleProgramDelete = (program, project) => {
        Modal.confirm({
            title: 'Delete Program',
            content: (
                <div>
                    <p>Are you sure you want to delete the program <strong>"{program.displayName}"</strong>?</p>
                    <p style={{ color: '#ff4d4f', marginBottom: 0 }}>This action cannot be undone.</p>
                </div>
            ),
            okText: 'Delete',
            okType: 'danger',
            cancelText: 'Cancel',
            width: 450,
            onOk: () => {
                return this.deleteProgram(program.id, project.id);
            },
        });
    };

    handleThematicAreaDelete = (thematicArea) => {
        Modal.confirm({
            title: 'Delete Thematic Area',
            content: (
                <div>
                    <p>Are you sure you want to delete the thematic area <strong>"{thematicArea.displayName}"</strong>?</p>
                    <p style={{ color: '#ff4d4f', marginBottom: 0 }}>This action will also delete all associated projects and programs. This cannot be undone.</p>
                </div>
            ),
            okText: 'Delete',
            okType: 'danger',
            cancelText: 'Cancel',
            width: 450,
            onOk: () => {
                return this.deleteThematicArea(thematicArea.id);
            },
        });
    };

    deleteProgram = async (programId, projectId) => {
        this.setState({ deletingProgramId: programId });

        try {
            const response = await fetch(`http://44.205.112.15:8080/api/29/programs/${programId}`, {
                method: 'DELETE',
                headers: {
                    'Authorization': 'Basic ' + btoa(`admin:district`),
                    'Content-Type': 'application/json'
                }
            });

            if (!response.ok) {
                throw new Error(`Failed to delete program: ${response.status} ${response.statusText}`);
            }

            // Remove the deleted program from state
            const updatedPrograms = { ...this.state.programs };
            if (updatedPrograms[projectId]) {
                updatedPrograms[projectId] = updatedPrograms[projectId].filter(program => program.id !== programId);
            }

            this.setState({
                programs: updatedPrograms,
                deletingProgramId: null
            });

            message.success('Program deleted successfully');
        } catch (error) {
            console.error('Error deleting program:', error);
            this.setState({ deletingProgramId: null });

            Modal.error({
                title: 'Delete Failed',
                content: `Failed to delete the program: ${error.message}`,
            });
        }
    };

    deleteThematicArea = async (thematicAreaId) => {
        this.setState({ deletingThematicAreaId: thematicAreaId });

        try {
            const response = await fetch(`http://44.205.112.15:8080/api/29/organisationUnits/${thematicAreaId}`, {
                method: 'DELETE',
                headers: {
                    'Authorization': 'Basic ' + btoa(`admin:district`),
                    'Content-Type': 'application/json'
                }
            });

            if (!response.ok) {
                throw new Error(`Failed to delete thematic area: ${response.status} ${response.statusText}`);
            }

            // Remove the deleted thematic area from state
            const updatedOrganisationUnits = this.state.organisationUnits.filter(unit => unit.id !== thematicAreaId);
            const updatedFilteredUnits = this.state.filteredOrganisationUnits.filter(unit => unit.id !== thematicAreaId);
            
            // Clean up related data
            const updatedProjects = { ...this.state.projects };
            const updatedPrograms = { ...this.state.programs };
            const updatedProjectsLoading = { ...this.state.projectsLoading };
            const updatedProgramsLoading = { ...this.state.programsLoading };
            const updatedProjectExpandedRowKeys = { ...this.state.projectExpandedRowKeys };
            
            delete updatedProjects[thematicAreaId];
            delete updatedProjectsLoading[thematicAreaId];
            delete updatedProjectExpandedRowKeys[thematicAreaId];
            
            // Remove programs data for all projects in this thematic area
            const projectsInArea = this.state.projects[thematicAreaId] || [];
            projectsInArea.forEach(project => {
                delete updatedPrograms[project.id];
                delete updatedProgramsLoading[project.id];
            });

            this.setState({
                organisationUnits: updatedOrganisationUnits,
                filteredOrganisationUnits: updatedFilteredUnits,
                projects: updatedProjects,
                programs: updatedPrograms,
                projectsLoading: updatedProjectsLoading,
                programsLoading: updatedProgramsLoading,
                projectExpandedRowKeys: updatedProjectExpandedRowKeys,
                deletingThematicAreaId: null,
                expandedRowKeys: this.state.expandedRowKeys.filter(key => key !== thematicAreaId)
            });

            message.success('Thematic area deleted successfully');
        } catch (error) {
            console.error('Error deleting thematic area:', error);
            this.setState({ deletingThematicAreaId: null });

            Modal.error({
                title: 'Delete Failed',
                content: `Failed to delete the thematic area: ${error.message}`,
            });
        }
    };

    handleCreateThematicArea = () => {
        // Navigate to create new thematic area (organization unit level 2)
        const redirectUrl = `/sims-web-maintenance/#/edit/organisationUnitSection/organisationUnit/add`;
        window.location.href = redirectUrl;
    };

    handleThematicAreaEdit = (thematicArea) => {
        // Navigate to edit thematic area (organization unit level 2)
        const redirectUrl = `/sims-web-maintenance/#/edit/organisationUnitSection/organisationUnit/${thematicArea.id}`;
        window.location.href = redirectUrl;
    };


    // Get more actions menu for programs
    getProgramActionsMenu = (program, project, thematicArea) => {
        const { deletingProgramId } = this.state;
        const isDeleting = deletingProgramId === program.id;

        return (
            <Menu>
                <Menu.Item key="edit" onClick={() => this.handleProgramClick(program, project)}>
                    <Icon type="edit" style={{ marginRight: '8px' }} />
                    Edit Program Details
                </Menu.Item>
                <Menu.Item key="view" onClick={() => this.handleProgramView(program, project, thematicArea)}>
                    <Icon type="eye" style={{ marginRight: '8px' }} />
                    View / Add Data
                </Menu.Item>
                <Menu.Divider />
                <Menu.Item
                    key="delete"
                    onClick={() => this.handleProgramDelete(program, project)}
                    disabled={isDeleting}
                    style={{ color: isDeleting ? '#ccc' : '#ff4d4f' }}
                >
                    <Icon type={isDeleting ? "loading" : "delete"} style={{ marginRight: '8px' }} />
                    {isDeleting ? 'Deleting...' : 'Delete Program'}
                </Menu.Item>
            </Menu>
        );
    };

    // Get actions menu for thematic areas
    getThematicAreaActionsMenu = (thematicArea) => {
        const { deletingThematicAreaId } = this.state;
        const isDeleting = deletingThematicAreaId === thematicArea.id;

        return (
            <Menu>
                <Menu.Item key="edit" onClick={() => this.handleThematicAreaEdit(thematicArea)}>
                    <Icon type="edit" style={{ marginRight: '8px' }} />
                    Edit Thematic Area
                </Menu.Item>
                <Menu.Divider />
                <Menu.Item
                    key="delete"
                    onClick={() => this.handleThematicAreaDelete(thematicArea)}
                    disabled={isDeleting}
                    style={{ color: isDeleting ? '#ccc' : '#ff4d4f' }}
                >
                    <Icon type={isDeleting ? "loading" : "delete"} style={{ marginRight: '8px' }} />
                    {isDeleting ? 'Deleting...' : 'Delete Thematic Area'}
                </Menu.Item>
            </Menu>
        );
    };

    // Render programs table for a project
    renderProgramsTable = (project, thematicAreaId) => {
        const { programs, programsLoading, searchValue, organisationUnits } = this.state;
        const projectPrograms = programs[project.id] || [];
        const isLoading = programsLoading[project.id];
        const thematicArea = organisationUnits.find(unit => unit.id === thematicAreaId);

        if (isLoading) {
            return (
                <div style={{ textAlign: 'center', padding: '16px' }}>
                    <Spin size="small" />
                    <div style={{ marginTop: '8px', color: '#666' }}>Loading programs...</div>
                </div>
            );
        }

        if (projectPrograms.length === 0) {
            return (
                <div style={{
                    padding: '16px',
                    textAlign: 'center',
                    color: '#999',
                    fontStyle: 'italic'
                }}>
                    <Icon type="warning" style={{ marginRight: '8px' }} />
                    No programs found in this project.
                </div>
            );
        }

        // Filter programs based on search
        let displayPrograms = projectPrograms;
        if (searchValue && searchValue.trim()) {
            const searchTerm = searchValue.toLowerCase();
            displayPrograms = projectPrograms.filter(program =>
                program.displayName.toLowerCase().includes(searchTerm) ||
                program.id.toLowerCase().includes(searchTerm) ||
                (program.code && program.code.toLowerCase().includes(searchTerm))
            );
        }

        const programColumns = [
            {
                title: 'Program Name',
                dataIndex: 'displayName',
                key: 'displayName',
                render: (text, program) => {
                    let displayText = text;
                    if (searchValue && searchValue.trim()) {
                        const searchTerm = searchValue.toLowerCase();
                        if (text.toLowerCase().includes(searchTerm)) {
                            const regex = new RegExp(`(${searchValue})`, 'gi');
                            displayText = text.replace(regex, '<mark>$1</mark>');
                        }
                    }

                    return (
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <Icon type="file-text" style={{ color: '#52c41a', marginRight: '8px' }} />
                            <span
                                style={{ fontWeight: '500' }}
                                dangerouslySetInnerHTML={{ __html: displayText }}
                            />
                        </div>
                    );
                }
            },
            {
                title: 'Actions',
                key: 'actions',
                width: 120,
                render: (text, program) => (
                    <Dropdown
                        overlay={this.getProgramActionsMenu(program, project, thematicArea)}
                        trigger={['click']}
                        placement="bottomRight"
                    >
                        <Button size="small" icon="more">
                        </Button>
                    </Dropdown>
                )
            }
        ];

        return (
            <Table
                columns={programColumns}
                dataSource={displayPrograms}
                pagination={false}
                size="small"
                rowKey="id"
                bordered={false}
                style={{ margin: '0 16px 16px 16px' }}
            />
        );
    };

    // Render projects table for a thematic area
    expandedRowRender = (thematicArea) => {
        const { projects, projectsLoading, searchValue, projectExpandedRowKeys } = this.state;
        const areaProjects = projects[thematicArea.id] || [];
        const isLoading = projectsLoading[thematicArea.id];

        if (isLoading) {
            return (
                <div style={{ textAlign: 'center', padding: '24px' }}>
                    <Spin size="small" />
                    <div style={{ marginTop: '8px', color: '#666' }}>Loading projects...</div>
                </div>
            );
        }

        if (areaProjects.length === 0) {
            return (
                <div style={{
                    padding: '16px',
                    textAlign: 'center',
                    color: '#999',
                    fontStyle: 'italic'
                }}>
                    <Icon type="warning" style={{ marginRight: '8px' }} />
                    No projects found in this thematic area.
                </div>
            );
        }

        // Filter projects based on search
        let displayProjects = areaProjects;
        if (searchValue && searchValue.trim()) {
            const searchTerm = searchValue.toLowerCase();
            displayProjects = areaProjects.filter(project => {
                const projectMatches = project.displayName.toLowerCase().includes(searchTerm) ||
                    project.id.toLowerCase().includes(searchTerm) ||
                    (project.code && project.code.toLowerCase().includes(searchTerm));

                // Also check if any programs in this project match
                const projectPrograms = this.state.programs[project.id] || [];
                const programMatches = projectPrograms.some(program =>
                    program.displayName.toLowerCase().includes(searchTerm) ||
                    program.id.toLowerCase().includes(searchTerm) ||
                    (program.code && program.code.toLowerCase().includes(searchTerm))
                );

                return projectMatches || programMatches;
            });
        }

        const projectColumns = [
            {
                title: 'Project Name',
                dataIndex: 'displayName',
                key: 'displayName',
                render: (text, project) => {
                    let displayText = text;
                    if (searchValue && searchValue.trim()) {
                        const searchTerm = searchValue.toLowerCase();
                        if (text.toLowerCase().includes(searchTerm)) {
                            const regex = new RegExp(`(${searchValue})`, 'gi');
                            displayText = text.replace(regex, '<mark>$1</mark>');
                        }
                    }

                    return (
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <Icon type="project" style={{ color: '#fa8c16', marginRight: '8px', fontSize: '14px' }} />
                            <span
                                style={{ fontWeight: '500', fontSize: '14px' }}
                                dangerouslySetInnerHTML={{ __html: displayText }}
                            />
                        </div>
                    );
                }
            },
        ];

        return (
            <div style={{ margin: '0 24px 24px 24px' }}>
                <Table
                    columns={projectColumns}
                    dataSource={displayProjects}
                    pagination={false}
                    size="small"
                    rowKey="id"
                    bordered={false}
                    expandedRowRender={(project) => this.renderProgramsTable(project, thematicArea.id)}
                    onExpand={(expanded, project) => this.handleProjectExpand(expanded, project, thematicArea.id)}
                    expandedRowKeys={projectExpandedRowKeys[thematicArea.id] || []}
                />
            </div>
        );
    };

    render() {
        const { organisationUnits, loading, error, searchValue, filteredOrganisationUnits, expandedRowKeys } = this.state;

        const cardStyle = {
            margin: '20px auto',
            maxWidth: '1200px',
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
        };

        const headerStyle = {
            padding: '24px',
            borderRadius: '8px 8px 0 0',
        };

        if (loading) {
            return (
                <Card style={cardStyle}>
                    <div style={{ textAlign: 'center', padding: '60px 0' }}>
                        <Spin size="large" />
                        <div style={{ marginTop: '16px', fontSize: '16px', color: '#666' }}>
                            Loading thematic areas...
                        </div>
                    </div>
                </Card>
            );
        }

        if (error) {
            return (
                <Card style={cardStyle}>
                    <div style={{ padding: '40px' }}>
                        <Alert
                            message="Error Loading Data"
                            description={error}
                            type="error"
                            showIcon
                            action={
                                <Button size="small" type="primary" onClick={this.fetchThematicAreas}>
                                    Try Again
                                </Button>
                            }
                        />
                    </div>
                </Card>
            );
        }

        const columns = [
            {
                title: 'Thematic Area',
                dataIndex: 'displayName',
                key: 'displayName',
                render: (text, record) => {
                    let displayText = text;
                    if (searchValue && searchValue.trim()) {
                        const searchTerm = searchValue.toLowerCase();
                        if (text.toLowerCase().includes(searchTerm)) {
                            const regex = new RegExp(`(${searchValue})`, 'gi');
                            displayText = text.replace(regex, '<mark>$1</mark>');
                        }
                    }

                    return (
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <Icon type="folder" style={{ color: '#1890ff', marginRight: '8px', fontSize: '16px' }} />
                            <span
                                style={{ fontWeight: '500', fontSize: '16px' }}
                                dangerouslySetInnerHTML={{ __html: displayText }}
                            />
                        </div>
                    );
                }
            },
            {
                title: 'Actions',
                key: 'actions',
                width: 120,
                render: (text, thematicArea) => (
                    <Dropdown
                        overlay={this.getThematicAreaActionsMenu(thematicArea)}
                        trigger={['click']}
                        placement="bottomRight"
                    >
                        <Button size="small" icon="more">
                        </Button>
                    </Dropdown>
                )
            }
        ];

        const dataSource = searchValue ? filteredOrganisationUnits : organisationUnits;

        return (
            <div>
                <Card bodyStyle={{ padding: 0 }}>
                    {/* Header */}
                    <div style={headerStyle}>
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <div>
                                <h1 style={{
                                    margin: 0,
                                    fontSize: '24px',
                                    fontWeight: 'bold',
                                }}>
                                    Thematic Areas
                                </h1>
                                <p style={{ margin: '8px 0 0 0', color: '#666' }}>
                                    Navigate through Thematic Areas → Projects → Programs using the expand icons
                                </p>
                            </div>
                        </div>
                    </div>

                    {/* Table Content */}
                    <div style={{ padding: '0 24px 24px 24px' }}>
                        {organisationUnits.length === 0 ? (
                            <div style={{ textAlign: 'center', padding: '60px 0', color: '#999' }}>
                                <Icon type="folder-open" style={{ fontSize: '64px', color: '#d9d9d9', marginBottom: '16px' }} />
                                <div style={{ fontSize: '16px' }}>No thematic areas found</div>
                            </div>
                        ) : (
                            <div>
                                <Search
                                    placeholder="Search across thematic areas, projects, and programs by name, code or ID"
                                    value={searchValue}
                                    onChange={(e) => this.handleSearch(e.target.value)}
                                    style={{ width: 500, marginBottom: 16 }}
                                />
                                {searchValue && (
                                    <div style={{ marginBottom: 16, color: '#666', fontSize: '14px' }}>
                                        <Icon type="search" style={{ marginRight: '4px' }} />
                                        Found {dataSource.length} thematic area(s) for "{searchValue}"
                                        {dataSource.length > 0 && expandedRowKeys.length > 0 && (
                                            <span style={{ marginLeft: '8px', color: '#1890ff' }}>
                                                (Matching items are automatically expanded)
                                            </span>
                                        )}
                                    </div>
                                )}
                                <Table
                                    columns={columns}
                                    dataSource={dataSource}
                                    rowKey="id"
                                    expandedRowRender={this.expandedRowRender}
                                    onExpand={this.handleThematicAreaExpand}
                                    expandedRowKeys={expandedRowKeys}
                                    onExpandedRowsChange={(keys) => this.setState({ expandedRowKeys: keys })}
                                    pagination={{
                                        pageSize: 10,
                                        showSizeChanger: true,
                                        showQuickJumper: true,
                                        showTotal: (total, range) =>
                                            `${range[0]}-${range[1]} of ${total} ${searchValue ? 'filtered' : ''} thematic areas`,
                                    }}
                                    size="middle"
                                />
                            </div>
                        )}
                    </div>
                </Card>

                {/* Floating Add Thematic Area Button */}
                <div style={{
                    position: 'fixed',
                    bottom: '24px',
                    right: '24px',
                    zIndex: 1000
                }}>
                    <Button
                        type="primary"
                        size="large"
                        shape="circle"
                        icon="plus"
                        onClick={this.handleCreateThematicArea}
                        style={{
                            width: '56px',
                            height: '56px',
                            fontSize: '20px',
                            boxShadow: '0 4px 12px rgba(24, 144, 255, 0.3)',
                            border: 'none'
                        }}
                        title="Add New Thematic Area"
                    />
                </div>
            </div>
        );
    }
}

export default ThematicAreaList;



